// src/app/configuration-base/configuration-base.component.ts
var ConfigurationBaseComponent = class {
  constructor(eventService, loader, monitoringService) {
    this.eventService = eventService;
    this.loader = loader;
    this.monitoringService = monitoringService;
    this.monitoringStates = MONITORING_STATE;
    this.editableStates = [MONITORING_STATE.READY];
  }
  initialize() {
    this.monitoringService.getMonitoringState().subscribe({
      next: monitoringState => {
        this.monitoringState = monitoringState;
        this.onStateChange();
      },
      error: _ => {
        this.monitoringState = MONITORING_STATE.UNDEFINED;
        this.onStateChange();
      }
    });
    this.eventService.isConnected().subscribe(connected => {
      if (connected) {
        this.loader.clearMessage();
      } else {
        this.monitoringState = MONITORING_STATE.UNDEFINED;
        this.onStateChange();
      }
    });
    this.baseSubscriptions = [this.eventService.listen("system_state_change").subscribe(monitoringState => {
      this.monitoringState = string2MonitoringState(monitoringState);
      this.onStateChange();
    })];
  }
  destroy() {
    if (this.baseSubscriptions) {
      this.baseSubscriptions.forEach(_ => _.unsubscribe());
      this.baseSubscriptions = [];
    }
    this.loader.clearMessage();
    this.loader.display(false);
  }
  onStateChange() {
    if (this.monitoringState === MONITORING_STATE.ERROR) {
      this.loader.setMessage("The system is not working correctly, you can't make changes in the configuration!");
    } else if (this.monitoringState === MONITORING_STATE.UNDEFINED) {
      this.loader.setMessage("Lost connection to the security system!");
    } else if (!this.editableStates.includes(this.monitoringState)) {
      this.loader.setMessage("The system is not ready, you can't make changes in the configuration!");
    } else {
      this.loader.clearMessage();
    }
  }
};

