// src/app/guards/admin.guard.ts
var AdminGuard = (router, state) => {
  const authService = inject2(AUTHENTICATION_SERVICE);
  if (authService.isLoggedIn()) {
    if (authService.getRole() === "admin") {
      return true;
    } else {
      inject2(Router).navigate(["/"]);
      return false;
    }
  }
  localStorage.setItem("returnUrl", JSON.stringify(state.url));
  inject2(Router).navigate(["/login"]);
  return false;
};

// src/app/guards/auth.guard.ts
var AuthGuard = (router, state) => {
  const authService = inject2(AUTHENTICATION_SERVICE);
  if (authService.isLoggedIn()) {
    return true;
  }
  localStorage.setItem("returnUrl", JSON.stringify(state.url));
  inject2(Router).navigate(["/login"]);
  return false;
};

// src/app/guards/setup.guard.ts
var setupGuard = (route, state) => {
  const locations = localStorage.getItem("locations");
  const selectedLocationId = localStorage.getItem("selectedLocationId");
  if (locations && selectedLocationId != null) {
    return true;
  } else {
    if (!environment.isMultiLocation) {
      return inject2(Router).createUrlTree(["/location/add"]);
    }
    return true;
  }
};

