var locale2 = localStorage.getItem("localeId");
console.log("Selected language: ", locale2);
if (locale2 === null) {
  locale2 = "en";
}
moment2.locale(locale2);
console.log("Current path: ", location.pathname);
var pathParser = new RegExp("^(?<version>/v\\d*-?[a-zA-Z]*)?/(?<language>[a-z]{2})/(?<path>.*)$");
var matches = pathParser.exec(location.pathname);
if (matches) {
  console.log("Path matches: ", matches);
  const newPath = [matches.groups.version, locale2, matches.groups.path].join("/");
  if (newPath !== location.pathname) {
    console.log("Redirect to " + newPath);
    location.pathname = newPath;
  } else {
    console.log("No need to redirect");
  }
} else {
  console.error("Path does not match", location.pathname);
}
if (environment.production) {
  enableProdMode();
}
platformBrowser().bootstrapModule(AppModule, {
  applicationProviders: [provideZoneChangeDetection()]
});
